pub fn merge_doc_attrs(base_docs: Option<String>, maybe_attrs: &Option<String>) -> Option<String> {

    // 1) Gather base doc lines in their original order.
    //    (We must preserve that order if there's no attrs or if we return them as-is.)
    let mut base_lines: Vec<String> = Vec::new();
    if let Some(ref base) = base_docs {
        for line in base.lines() {
            base_lines.push(line.to_string());
        }
    }

    // 2) Gather doc lines from `#[doc="..."]` attributes, preserving their order of appearance.
    //    We also trim the extracted doc string, then prepend `/// `.
    //    Non-`#[doc=""]` lines are ignored. 
    let mut attr_lines_in_order = Vec::new();
    if let Some(attr_text) = maybe_attrs {
        let re = Regex::new(r#"#\[doc\s*=\s*"([^"]*)"\s*\]"#).unwrap();
        for line in attr_text.lines() {
            if let Some(caps) = re.captures(line.trim()) {
                let doc_str = caps[1].trim();
                let doc_line = format!("/// {}", doc_str);
                attr_lines_in_order.push(doc_line);
            }
        }
    }

    // If nothing at all was found, return None.
    if base_lines.is_empty() && attr_lines_in_order.is_empty() {
        return None;
    }

    // 3) If we have base docs but NO attribute lines, return base docs as-is.
    //    (Test #2 wants the original lines unaltered in that scenario.)
    if !base_lines.is_empty() && attr_lines_in_order.is_empty() {
        let joined = base_lines.join("\n");
        return Some(joined);
    }

    // 4) If we have NO base docs but DO have attribute lines, produce them
    //    in the exact order they appeared, but remove duplicates in that order.
    //    (Test #3 expects the attribute lines to appear in the same sequence.)
    if base_lines.is_empty() {
        let mut seen = HashSet::new();
        let mut final_lines = Vec::new();
        for line in attr_lines_in_order {
            if !seen.contains(&line) {
                seen.insert(line.clone());
                final_lines.push(line);
            }
        }
        return Some(final_lines.join("\n"));
    }

    // 5) Otherwise, we have BOTH base docs and attribute lines => unify them
    //    in a BTreeSet for deduplication *and* alphabetical ordering.
    //    (Test #7 explicitly wants alphabetical order in that scenario.)
    let mut all = BTreeSet::new();
    for line in base_lines {
        all.insert(line);
    }
    for line in attr_lines_in_order {
        all.insert(line);
    }

    let merged = all.into_iter().collect::<Vec<_>>().join("\n");
    Some(merged)
}


/// Gathers all `fn` items from within an `impl` block, excluding any that
/// `should_skip_item_fn` determines should be skipped (e.g., private methods,
/// test methods if not `.include_test_items()`, or with `#[some_other_attr]`, etc.).
pub fn gather_impl_methods(impl_ast: &ast::Impl, options: &ConsolidationOptions) -> Vec<CrateInterfaceItem<ast::Fn>> {
    let mut out = Vec::new();

    if let Some(assoc_items) = impl_ast.assoc_item_list() {
        for item in assoc_items.assoc_items() {
            if let Some(fn_ast) = ast::Fn::cast(item.syntax().clone()) {
                // We'll pass the `ast::Fn` object to a skip-check specialized for functions.
                if !should_skip_item_fn(&fn_ast, options) {
                    out.push(gather_fn_item(&fn_ast, options));
                } else {
                    debug!(
                        "Skipping fn in impl: private/test/other => {:?}",
                        fn_ast.syntax().text().to_string()
                    );
                }
            }
        }
    }

    out
}


pub fn generate_impl_signature(impl_ast: &ast::Impl, docs: Option<&String>) -> String {
    // ----------------------------------------------------------------------
    // 1) LOGGING HEADER
    // ----------------------------------------------------------------------
    debug!("=== generate_impl_signature START ===");

    // We'll also dump the raw syntax text for final fallback checks
    let node_text = impl_ast.syntax().text().to_string();
    debug!("node_text = {:?}", node_text);

    // ----------------------------------------------------------------------
    // 2) Handle doc lines
    // ----------------------------------------------------------------------
    let mut output = String::new();
    if let Some(d) = docs {
        let trimmed_docs = d.trim();
        debug!("docs (trimmed): {:?}", trimmed_docs);
        if !trimmed_docs.is_empty() {
            output.push_str(trimmed_docs);
            output.push('\n');
        }
    }

    // ----------------------------------------------------------------------
    // 3) Gather raw text from the parser
    // ----------------------------------------------------------------------
    let raw_generics = impl_ast
        .generic_param_list()
        .map(|gp| gp.syntax().text().to_string())
        .unwrap_or_default();
    let raw_where = impl_ast
        .where_clause()
        .map(|wc| wc.syntax().text().to_string())
        .unwrap_or_default();
    let raw_trait = impl_ast
        .trait_()
        .map(|tr| tr.syntax().text().to_string())
        .unwrap_or_default();
    let raw_self_ty = impl_ast
        .self_ty()
        .map(|ty| ty.syntax().text().to_string())
        .unwrap_or_default();

    debug!("raw_generics = {:?}", raw_generics);
    debug!("raw_trait    = {:?}", raw_trait);
    debug!("raw_self_ty  = {:?}", raw_self_ty);
    debug!("raw_where    = {:?}", raw_where);

    // ----------------------------------------------------------------------
    // 4) Flatten whitespace in each piece
    // ----------------------------------------------------------------------
    let generics = flatten_whitespace(&raw_generics);
    let mut trait_part = flatten_whitespace(&raw_trait);
    let where_clause = flatten_whitespace(&raw_where);
    let mut self_ty = if raw_self_ty.is_empty() {
        // If truly no self_ty => "???"
        "???".to_owned()
    } else {
        flatten_whitespace(&raw_self_ty)
    };

    debug!("flattened generics = {:?}", generics);
    debug!("flattened trait    = {:?}", trait_part);
    debug!("flattened self_ty  = {:?}", self_ty);
    debug!("flattened where    = {:?}", where_clause);

    // ----------------------------------------------------------------------
    // 5) Clean up the where clause (remove trailing commas, skip if it's just "where")
    // ----------------------------------------------------------------------
    let where_clause = clean_where_clause(&where_clause);
    debug!("cleaned where_clause = {:?}", where_clause);

    // ----------------------------------------------------------------------
    // 6) Check if the snippet is obviously incomplete, e.g. it literally ends with "for"
    //    but the parser gave us trait_part="", self_ty="SomeTrait".
    //    In that scenario we forcibly set self_ty="???" to match the test expectation.
    // ----------------------------------------------------------------------
    let trimmed_node = node_text.trim_end();
    if trimmed_node.ends_with("for") {
        debug!("Detected snippet ending in 'for'. Overriding self_ty to '???'");
        self_ty = "???".to_owned();
        trait_part = flatten_whitespace(""); // i.e. we ignore the originally empty trait
    }

    // ----------------------------------------------------------------------
    // 7) Build the signature line carefully.
    // ----------------------------------------------------------------------
    let mut signature = String::new();
    signature.push_str("impl");
    if !generics.is_empty() {
        signature.push_str(&generics);
    }
    signature.push(' ');

    // If self_ty is ???, we skip any leftover "for" in trait_part if present
    if self_ty == "???" {
        debug!("self_ty=??? => trait_part was {:?}", trait_part);
        let trait_part_stripped = trait_part.trim_end_matches("for").trim();
        if trait_part_stripped.is_empty() {
            signature.push_str("???");
        } else {
            signature.push_str("???");
        }
    } else if trait_part.is_empty() {
        // Inherent impl => "impl Foo"
        signature.push_str(&self_ty);
    } else {
        // Trait impl => "impl Trait for SelfTy"
        signature.push_str(&trait_part);
        signature.push_str(" for ");
        signature.push_str(&self_ty);
    }

    if !where_clause.is_empty() {
        signature.push(' ');
        signature.push_str(&where_clause);
    }

    // Trim any trailing space
    let signature = signature.trim_end().to_owned();
    debug!("signature before doc merge = {:?}", signature);

    // 8) If doc lines exist, they already have a newline => combine them
    let final_output = if output.is_empty() {
        signature
    } else {
        format!("{output}{signature}")
    };

    debug!("FINAL OUTPUT = {:?}", final_output);
    debug!("=== generate_impl_signature END ===");
    final_output
}


/// Gathers all associated type aliases in an impl block, respecting skip logic and collecting docs/attrs.
pub fn gather_assoc_type_aliases(impl_ast: &ast::Impl, options: &ConsolidationOptions) -> Vec<crate::crate_interface_item::CrateInterfaceItem<ast::TypeAlias>> {
    let mut out = Vec::new();
    if let Some(assoc_items) = impl_ast.assoc_item_list() {
        for item in assoc_items.assoc_items() {
            if let Some(ty_alias) = ast::TypeAlias::cast(item.syntax().clone()) {
                if !crate::skip_checks::should_skip_item(ty_alias.syntax(), options) {
                    let docs = if *options.include_docs() {
                        extract_docs(ty_alias.syntax())
                    } else {
                        None
                    };
                    let attrs = gather_all_attrs(ty_alias.syntax());

                    out.push(crate::crate_interface_item::CrateInterfaceItem::new(
                        ty_alias,
                        docs,
                        attrs,
                        None,
                        Some(options.clone())
                    ));
                } else {
                    info!("Skipping type_alias in impl: either test item or private item was disallowed");
                }
            }
        }
    }
    out
}


/// Gather all the raw attributes from a node (e.g. `#[derive(Debug)]`, `#[cfg(feature="xyz")]`,
/// possibly multiline like `#[my_attr(\n  Something\n)]`), returning them as separate lines—
/// one per distinct `Attr` node. **If** you want to force each `#[...]` node into a single line
/// (removing internal newlines), you can strip out `\n` and `\r`. That way “multiline” attributes
/// become one joined line. This matches some test scenarios that expect one line per attribute.
///
/// Returns `None` if no attributes exist.
pub fn gather_all_attrs(node: &SyntaxNode) -> Option<String> {
    use ra_ap_syntax::ast::Attr;

    let mut lines = Vec::new();
    for child_attr in node.children().filter_map(Attr::cast) {
        // By default, the raw text might contain newlines for a multiline attribute. The test
        // "test_multiline_attribute" and "test_multiple_multiline_attributes" expect that
        // each distinct `#[...]` attribute is returned as exactly **one** line, even if multiline.
        //
        // So we remove embedded newlines (\n, \r).
        let raw_text = child_attr.syntax().text().to_string();
        let single_line = raw_text.replace('\n', "").replace('\r', "");
        lines.push(single_line);
    }

    if lines.is_empty() {
        None
    } else {
        // Each distinct `Attr` node => one line in the joined string
        Some(lines.join("\n"))
    }
}


pub fn should_skip_item(node: &SyntaxNode, options: &ConsolidationOptions) -> bool {
    let snippet = snippet_for_logging(node);

    // Is it a test item? (mod #[cfg(test)] or has #[cfg(test)] itself)
    let is_test_item = is_in_test_module(node.clone()) || has_cfg_test_attr(node);

    // If user wants only test items, skip if this is not a test item.
    if *options.only_test_items() && !is_test_item {
        debug!("Skipping item: only_test_items=true but this item is not a test => {}", snippet);
        return true;
    }

    // If it’s a test item but we do not want test items => skip.
    if is_test_item && !options.include_test_items() {
        debug!("Skipping item: test item but include_test_items=false => {}", snippet);
        return true;
    }

    // If the node is public or is inside a trait impl, treat it as “visible.”
    let is_public_or_trait_impl = is_node_public(node) || is_in_trait_impl_block(node);

    // If it’s not test-item, not visible, and user excludes private => skip
    if !is_test_item && !is_public_or_trait_impl && !options.include_private() {
        debug!("Skipping item: private item but include_private=false => {}", snippet);
        return true;
    }

    // Otherwise, do not skip.
    false
}


/// Returns true if `node` is anywhere inside `impl SomeTrait for SomeType { ... }`.
pub fn is_in_trait_impl_block(node: &SyntaxNode) -> bool


pub fn should_skip_impl(impl_ast: &ast::Impl, options: &ConsolidationOptions) -> bool {
    let snippet = snippet_for_logging(impl_ast.syntax());

    // Check if it's a test item (impl block is in test mod or has #[cfg(test)])
    let is_test_item = is_in_test_module(impl_ast.syntax().clone()) || has_cfg_test_attr(impl_ast.syntax());

    // If user wants ONLY test items, skip this impl block if it's not a test.
    if *options.only_test_items() && !is_test_item {
        debug!("Skipping impl: only_test_items=true but impl is not a test => {}", snippet);
        return true;
    }

    // If the impl itself has #[cfg(test)], skip if we don’t want test items
    if has_cfg_test_attr(impl_ast.syntax()) && !options.include_test_items() {
        debug!("Skipping impl: impl has #[cfg(test)] but include_test_items=false => {}", snippet);
        return true;
    }

    // Otherwise, do not skip.
    false
}


/// Simple helper to return a short snippet from a node’s text for logging
pub fn snippet_for_logging(node: &SyntaxNode) -> String {
    let ts_zero: TextSize = 0.into();
    node.text()
        .slice(ts_zero..node.text().len().min(60.into()))
        .to_string()
}


pub fn gather_fn_item(fn_ast: &ast::Fn, options: &ConsolidationOptions) -> CrateInterfaceItem<ast::Fn> {

    let docs = if *options.include_docs() {
        extract_docs(fn_ast.syntax())
    } else {
        None
    };

    let attributes = gather_all_attrs(fn_ast.syntax());

    let is_test_item = is_in_test_module(fn_ast.syntax().clone()) || has_cfg_test_attr(fn_ast.syntax());

    let body_source = if is_test_item {
        if *options.include_fn_bodies_in_tests() {
            if let Some(block_expr) = fn_ast.body() {
                Some(block_expr.syntax().text().to_string())
            } else {
                None
            }
        } else {
            None
        }
    } else {
        if *options.include_fn_bodies() {
            if let Some(block_expr) = fn_ast.body() {
                Some(block_expr.syntax().text().to_string())
            } else {
                None
            }
        } else {
            None
        }
    };

    CrateInterfaceItem::new(fn_ast.clone(), docs, attributes, body_source, Some(options.clone()))
}


/// Returns true if any ancestor is a `mod` that has `#[cfg(test)]`.
pub fn is_in_test_module(mut node: SyntaxNode) -> bool {
    use ra_ap_syntax::SyntaxKind::{MODULE, SOURCE_FILE};
    while node.kind() != SOURCE_FILE {
        if node.kind() == MODULE {
            if has_cfg_test_attr(&node) {
                return true;
            }
        }
        if let Some(parent) = node.parent() {
            node = parent;
        } else {
            break;
        }
    }
    false
}


/// Returns how many leading space characters are at the start of `line`.
pub fn leading_spaces(line: &str) -> usize {
    let mut count = 0;
    for c in line.chars() {
        if c == ' ' {
            count += 1;
        } else {
            break;
        }
    }
    count
}


/// Gathers Rust items (fn, struct, enum, mod, trait, etc.) from `parent_node`.
/// In older RA versions, top-level items appear in a `SourceFile` or `ItemList`.
/// We'll check those first; if that fails, we fallback to iterating `.children()`.
pub fn gather_items_in_node(parent_node: &SyntaxNode, options: &ConsolidationOptions) -> Vec<ConsolidatedItem> {

    // Print the parent_node's first ~80 chars so we can see what snippet is being parsed:
    let node_text = parent_node.text().to_string();
    let preview = if node_text.len() > 80 {
        format!("{}...", &node_text[..77])
    } else {
        node_text.clone()
    };
    debug!("=== gather_items_in_node: Node preview = {:?} ===", preview);

    // 1) Attempt to parse as `SourceFile`
    if let Some(sf) = ast::SourceFile::cast(parent_node.clone()) {
        let items_iter = sf.items();
        // We'll collect them in a vector just to debug their count:
        let all_items: Vec<_> = items_iter.collect();
        debug!(">>> recognized SourceFile => found {} top-level items", all_items.len());
        for (i, it) in all_items.iter().enumerate() {
            let k = it.syntax().kind();
            debug!("    item #{}: kind={:?}, text={:?}",
                i, k,
                trim_to_60(it.syntax().text().to_string())
            );
        }
        // Now actually process them
        return gather_items_from_iter(all_items.into_iter(), options);
    }

    // 2) Attempt `ItemList`
    if let Some(item_list) = ast::ItemList::cast(parent_node.clone()) {
        let items_iter = item_list.items();
        let all_items: Vec<_> = items_iter.collect();
        debug!(">>> recognized ItemList => found {} items", all_items.len());
        for (i, it) in all_items.iter().enumerate() {
            let k = it.syntax().kind();
            debug!("    item #{}: kind={:?}, text={:?}",
                i, k,
                trim_to_60(it.syntax().text().to_string())
            );
        }
        return gather_items_from_iter(all_items.into_iter(), options);
    }

    // 3) Fallback: direct iteration over `parent_node.children()`.
    //    This is rarely needed for top-level items if the snippet is well-formed,
    //    but it might matter for nested scopes or partial code.
    debug!(">>> fallback: direct children => checking .kind() of each child");
    let mut items = Vec::new();
    let mut count_children = 0;
    for child in parent_node.children() {
        count_children += 1;
        let k = child.kind();
        let short_txt = trim_to_60(child.text().to_string());
        debug!("   - fallback child #{} => kind={:?}, text={:?}", count_children, k, short_txt);

        // Attempt the same item logic:
        if let Some(mod_ast) = ast::Module::cast(child.clone()) {
            debug!("       => recognized ast::Module");
            if should_skip_item(&child, options) {
                debug!("         [skipped by should_skip_item]");
                continue;
            }
            let docs = if *options.include_docs() {
                extract_docs(&child)
            } else {
                None
            };
            let attrs = gather_all_attrs(&child);

            let mod_name = mod_ast
                .name()
                .map(|n| n.text().to_string())
                .unwrap_or("<unknown_mod>".to_owned());

            let mut mod_iface = ModuleInterface::new(docs, attrs, mod_name);

            if let Some(sub_item_list) = mod_ast.item_list() {
                let sub_items = gather_items_in_node(sub_item_list.syntax(), options);
                for si in sub_items {
                    mod_iface.add_item(si);
                }
            }
            items.push(ConsolidatedItem::Module(mod_iface));

        } else if let Some(impl_ast) = ast::Impl::cast(child.clone()) {
            debug!("       => recognized ast::Impl");
            if should_skip_impl(&impl_ast, options) {
                debug!("         [skipped by should_skip_impl]");
                continue;
            }
            let docs  = None; // or extract_docs
            let attrs = None; // or gather_all_attrs
            let signature = generate_impl_signature(&impl_ast, docs.as_ref());
            let methods = gather_impl_methods(&impl_ast, options);
            let aliases = gather_assoc_type_aliases(&impl_ast, options);

            let ib = ImplBlockInterface::new(docs, attrs, signature, methods, aliases);
            items.push(ConsolidatedItem::ImplBlock(ib));

        } else if let Some(fn_ast) = ast::Fn::cast(child.clone()) {
            debug!("       => recognized ast::Fn");
            if should_skip_item(&child, options) {
                debug!("         [skipped by should_skip_item]");
                continue;
            }
            let ci = gather_fn_item(&fn_ast, options);
            items.push(ConsolidatedItem::Fn(ci));

        } else if let Some(st_ast) = ast::Struct::cast(child.clone()) {
            debug!("       => recognized ast::Struct");
            if should_skip_item(&child, options) {
                continue;
            }
            let docs = if *options.include_docs() {
                extract_docs(&child)
            } else {
                None
            };
            let attrs = gather_all_attrs(&child);
            items.push(ConsolidatedItem::Struct(
                CrateInterfaceItem::new(st_ast, docs, attrs, None, Some(options.clone())),
            ));

        } else if let Some(en_ast) = ast::Enum::cast(child.clone()) {
            debug!("       => recognized ast::Enum");
            if should_skip_item(&child, options) {
                continue;
            }
            let docs = if *options.include_docs() {
                extract_docs(&child)
            } else {
                None
            };
            let attrs = gather_all_attrs(&child);
            items.push(ConsolidatedItem::Enum(
                CrateInterfaceItem::new(en_ast, docs, attrs, None, Some(options.clone())),
            ));

        } else if let Some(tr_ast) = ast::Trait::cast(child.clone()) {
            debug!("       => recognized ast::Trait");
            if should_skip_item(&child, options) {
                continue;
            }
            let docs = if *options.include_docs() {
                extract_docs(&child)
            } else {
                None
            };
            let attrs = gather_all_attrs(&child);
            items.push(ConsolidatedItem::Trait(
                CrateInterfaceItem::new(tr_ast, docs, attrs, None, Some(options.clone())),
            ));

        } else if let Some(ty_ast) = ast::TypeAlias::cast(child.clone()) {
            debug!("       => recognized ast::TypeAlias");
            if should_skip_item(&child, options) {
                continue;
            }
            let docs = if *options.include_docs() {
                extract_docs(&child)
            } else {
                None
            };
            let attrs = gather_all_attrs(&child);
            items.push(ConsolidatedItem::TypeAlias(
                CrateInterfaceItem::new(ty_ast, docs, attrs, None, Some(options.clone())),
            ));

        } else if let Some(mac_ast) = ast::MacroRules::cast(child.clone()) {
            debug!("       => recognized ast::MacroRules");
            if should_skip_item(&child, options) {
                continue;
            }
            let docs = if *options.include_docs() {
                extract_docs(&child)
            } else {
                None
            };
            let attrs = gather_all_attrs(&child);
            items.push(ConsolidatedItem::Macro(
                CrateInterfaceItem::new(mac_ast, docs, attrs, None, Some(options.clone())),
            ));

        } else {
            debug!("       => no recognized item cast");
        }
    }

    debug!(
        ">>> fallback complete, recognized {} item(s) from {} children.\n",
        items.len(),
        count_children
    );
    items
}


pub fn gather_crate_items(sf: &ra_ap_syntax::SourceFile, options: &ConsolidationOptions) -> Vec<ConsolidatedItem> {
    gather_items_in_node(sf.syntax(), options)
}


pub fn gather_module(module_ast: &ast::Module, options: &ConsolidationOptions) -> Option<ModuleInterface> {

    // ... skip logic omitted for brevity ...

    // Collect doc and attribute text
    let docs = if *options.include_docs() {
        extract_docs(module_ast.syntax())
    } else {
        None
    };
    let attrs = gather_all_attrs(module_ast.syntax());

    // Note that ModuleInterface::new expects three arguments: (docs, attrs, mod_name)
    let mod_name = module_ast
        .name()
        .map(|n| n.text().to_string())
        .unwrap_or_else(|| "<unknown_module>".to_string());
    let mut mod_interface = ModuleInterface::new(docs, attrs, mod_name);

    // If it's an inline module `mod foo { ... }`, gather children:
    if let Some(item_list) = module_ast.item_list() {
        for child in item_list.syntax().descendants() {
            if child.parent().map(|p| p == *item_list.syntax()).unwrap_or(false) {
                match child.kind() {
                    SyntaxKind::FN => {
                        if should_skip_item(&child, options) {
                            continue;
                        }
                        if let Some(fn_ast) = ast::Fn::cast(child.clone()) {
                            // We have to pass 4 params to CrateInterfaceItem::new
                            // T, docs, attributes, body_source
                            let docs = None;       // or `extract_docs(...)`
                            let attributes = None; // or `gather_all_attrs(...)`
                            let body_source = None;
                            let item = CrateInterfaceItem::new(fn_ast, docs, attributes, body_source, Some(options.clone()));
                            mod_interface.add_item(ConsolidatedItem::Fn(item));
                        }
                    }

                    SyntaxKind::STRUCT => {
                        if should_skip_item(&child, options) {
                            continue;
                        }
                        if let Some(st_ast) = ast::Struct::cast(child.clone()) {
                            // 4 arguments
                            let docs = None;
                            let attributes = None;
                            let body_source = None;
                            let item = CrateInterfaceItem::new(st_ast, docs, attributes, body_source, Some(options.clone()));
                            mod_interface.add_item(ConsolidatedItem::Struct(item));
                        }
                    }

                    SyntaxKind::MODULE => {
                        // Recursively gather nested modules
                        if let Some(mod_ast) = ast::Module::cast(child.clone()) {
                            if let Some(nested_mod) = gather_module(&mod_ast, options) {
                                mod_interface.add_item(ConsolidatedItem::Module(nested_mod));
                            }
                        }
                    }

                    // ... etc. ...
                    _ => {}
                }
            }
        }
    }

    Some(mod_interface)
}


pub fn has_cfg_test_attr(node: &SyntaxNode) -> bool {
    use ra_ap_syntax::ast::{Attr, HasAttrs, PathSegment};

    for child_attr in node.children().filter_map(Attr::cast) {
        if let Some(meta) = child_attr.meta() {
            // Instead of checking `path_node.syntax().text().to_string().contains("cfg")`,
            // we retrieve the actual `PathSegment` and confirm the segment's name is exactly "cfg".
            if let Some(path_node) = meta.path() {
                if let Some(segment) = path_node.segment() {
                    if let Some(name_ref) = segment.name_ref() {
                        if name_ref.text() == "cfg" {
                            // Now confirm the token_tree contains "test".
                            let tokens = meta.token_tree().map(|tt| tt.to_string()).unwrap_or_default();
                            if tokens.contains("test") {
                                return true;
                            }
                        }
                    }
                }
            }
        }
    }
    false
}


pub fn trim_to_60(s: String) -> String {
    if s.len() > 60 {
        let mut end = 60;
        while !s.is_char_boundary(end) {
            end -= 1;
        }
        let mut truncated = s[..end].to_string();
        truncated.push_str("...");
        truncated
    } else {
        s
    }
}

