impl<T> ::serde::Serialize for CrateInterfaceItem<T> where T: RehydrateFromSignature {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error> where
            S: ::serde::Serializer, {
        trace!("Serializing CrateInterfaceItem<T> manually.");

        // We have five fields to serialize:
        //   item_signature (String)      => from `self.item.generate_signature()`
        //   docs (Option<String>)
        //   attributes (Option<String>)
        //   body_source (Option<String>)
        //   consolidation_options (Option<ConsolidationOptions>)
        let mut state = serializer.serialize_struct("CrateInterfaceItem", 5)?;

        // 1) item_signature => always present
        let signature_str = self.item().generate_signature();
        state.serialize_field("item_signature", &signature_str)?;

        // 2) docs
        state.serialize_field("docs", &self.docs())?;

        // 3) attributes
        state.serialize_field("attributes", &self.attributes())?;

        // 4) body_source
        state.serialize_field("body_source", &self.body_source())?;

        // 5) consolidation_options
        state.serialize_field("consolidation_options", &self.consolidation_options())?;

        state.end()
    }
}

impl<'de, T> ::serde::Deserialize<'de> for CrateInterfaceItem<T> where T: RehydrateFromSignature {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error> where
            D: ::serde::Deserializer<'de>, {
        debug!("Deserializing CrateInterfaceItem<T> via a custom Visitor.");

        // The fields we expect:
        const FIELDS: &[&str] = &[
            "item_signature",
            "docs",
            "attributes",
            "body_source",
            "consolidation_options",
        ];

        // We define an enum to match the field names:
        #[derive(Deserialize)]
        #[serde(field_identifier, rename_all = "snake_case")]
        enum Field {
            ItemSignature,
            Docs,
            Attributes,
            BodySource,
            ConsolidationOptions,
        }

        // This Visitor will build our final CrateInterfaceItem<T>.
        struct CrateInterfaceItemVisitor<U: RehydrateFromSignature> {
            marker: PhantomData<fn() -> CrateInterfaceItem<U>>,
        }

        impl<'de, U> Visitor<'de> for CrateInterfaceItemVisitor<U>
        where
            U: RehydrateFromSignature,
        {
            type Value = CrateInterfaceItem<U>;

            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                write!(formatter, "struct CrateInterfaceItem")
            }

            fn visit_map<M>(self, mut map: M) -> Result<Self::Value, M::Error>
            where
                M: MapAccess<'de>,
            {
                trace!("Visiting map entries to deserialize CrateInterfaceItem<T>.");

                // We'll store each field in a local Option<...> variable until we have them all.
                let mut item_signature: Option<String> = None;
                let mut docs: Option<Option<String>> = None;
                let mut attributes: Option<Option<String>> = None;
                let mut body_source: Option<Option<String>> = None;
                let mut consolidation_opts: Option<Option<ConsolidationOptions>> = None;

                while let Some(key) = map.next_key()? {
                    match key {
                        Field::ItemSignature => {
                            // required => parse as a plain String
                            let sig: String = map.next_value()?;
                            item_signature = Some(sig);
                        }
                        Field::Docs => {
                            // optional => parse as Option<String>
                            docs = Some(map.next_value::<Option<String>>()?);
                        }
                        Field::Attributes => {
                            attributes = Some(map.next_value::<Option<String>>()?);
                        }
                        Field::BodySource => {
                            body_source = Some(map.next_value::<Option<String>>()?);
                        }
                        Field::ConsolidationOptions => {
                            // parse as Option<ConsolidationOptions>, so null => None
                            consolidation_opts = Some(map.next_value::<Option<ConsolidationOptions>>()?);
                        }
                    }
                }

                // item_signature is required:
                let item_signature =
                    item_signature.ok_or_else(|| DeError::missing_field("item_signature"))?;

                // Rehydrate T from the signature string:
                let rehydrated_item = U::rehydrate_from_signature(&item_signature).ok_or_else(|| {
                    DeError::custom(format!("Failed to rehydrate `T` from signature: `{}`", item_signature))
                })?;

                trace!("Successfully rehydrated T from signature.");

                // Convert double-option to single
                let final_docs = docs.unwrap_or(None);
                let final_attrs = attributes.unwrap_or(None);
                let final_body = body_source.unwrap_or(None);
                let final_co = consolidation_opts.unwrap_or(None);

                // Build via the builder or directly:
                let item = CrateInterfaceItemBuilder::default()
                    .item(Arc::new(rehydrated_item))
                    .docs(final_docs)
                    .attributes(final_attrs)
                    .body_source(final_body)
                    .consolidation_options(final_co)
                    .build()
                    .map_err(DeError::custom)?;

                Ok(item)
            }
        }

        // Actually invoke the visitor:
        deserializer.deserialize_struct(
            "CrateInterfaceItem",
            FIELDS,
            CrateInterfaceItemVisitor {
                marker: PhantomData,
            },
        )
    }
}

impl Into<SignatureOptions> for &ConsolidationOptions {
    fn into(self) -> SignatureOptions {
        // 1) `include_docs` => whether we show doc lines
        // 2) `fully_expand` => do we show fields, variants, trait items, etc.
        //    Let’s pick a rule that if .include_fn_bodies() is true, we do fully_expand
        //    (or if you want more nuance, do something different).
        SignatureOptionsBuilder::default()
            .include_docs(*self.include_docs())
            .fully_expand(*self.include_fn_bodies())
            .build()
            .unwrap()
    }
}

impl ConsolidationOptions {
    /// Construct with all toggles turned off by default.
    pub fn new() -> Self {
        let opts = Self {
            include_docs:               false,
            include_private:            false,
            include_test_items:         false,
            include_fn_bodies:          false,
            include_fn_bodies_in_tests: false,
            only_test_items:            false,
        };
        opts.validate();
        opts
    }
    /// Turn on doc comment extraction (`include_docs = true`).
    pub fn with_docs(mut self) -> Self {
        self.include_docs = true;
        self
    }
    /// Include private items (e.g. non-`pub fn`, private structs, etc.).
    pub fn with_private_items(mut self) -> Self {
        self.include_private = true;
        self
    }
    /// Include test items (marked `#[cfg(test)]`, etc.).
    pub fn with_test_items(mut self) -> Self {
        self.include_test_items = true;
        self
    }
    /// Include function bodies for normal (non-test) items.
    pub fn with_fn_bodies(mut self) -> Self {
        self.include_fn_bodies = true;
        self
    }
    /// Include function bodies for test items. 
    /// (Separate from `with_fn_bodies`, in case you want bodies for non-test only.)
    pub fn with_fn_bodies_in_tests(mut self) -> Self {
        self.include_fn_bodies_in_tests = true;
        self
    }
    /// Show *only* test items, skipping everything else.
    /// Automatically sets `include_test_items = true` if not already set.
    pub fn with_only_test_items(mut self) -> Self {
        if !self.include_test_items {
            warn!("[WARN] `only_test_items=true` requires `include_test_items=true`. Forcing it on.");
            self.include_test_items = true;
        }
        self.only_test_items = true;
        self
    }
    /// A small validation method that logs warnings via `warn!` if 
    /// certain combinations of flags are contradictory or possibly confusing.
    pub fn validate(&self) {
        // Example: if you want to warn that `only_test_items` + `include_private` is mostly redundant:
        if self.only_test_items && self.include_private {
            warn!("[WARN] You set `only_test_items=true` and `include_private=true`. \
                       Private non-test items won't appear anyway (they're not test items), so this might be redundant.");
        }

        // Another example: if `only_test_items` + `include_fn_bodies` might not do anything for non-test items:
        if self.only_test_items && self.include_fn_bodies && !self.include_fn_bodies_in_tests {
            warn!("[WARN] `only_test_items=true` and `include_fn_bodies=true`, but no `include_fn_bodies_in_tests`. \
                       You won't see non-test bodies. Possibly you meant `.with_fn_bodies_in_tests()`?");
        }
        // etc. Expand for any combos you want to warn about.
    }
}

impl<T> ConsolidateCrateInterface for T where T : ReadFileString + GetSourceFilesWithExclusions + Sync + Send {
    async fn consolidate_crate_interface(&self, options: &ConsolidationOptions) -> Result<ConsolidatedCrateInterface, CrateError> {

        trace!("Consolidating crate interface.");

        let source_files = self.source_files_excluding(&[]).await?;
        let mut result = ConsolidatedCrateInterface::new();

        for file_path in source_files {
            let code         = self.read_file_string(&file_path).await?;
            let parse_result = SourceFile::parse(&code, Edition::Edition2024);
            let sf           = parse_result.tree();
            let items        = gather_crate_items(&sf, options);

            for item in items {
                match item {
                    ConsolidatedItem::Fn(ci)        => result.add_fn(ci),
                    ConsolidatedItem::Struct(ci)    => result.add_struct(ci),
                    ConsolidatedItem::Enum(ci)      => result.add_enum(ci),
                    ConsolidatedItem::Trait(ci)     => result.add_trait(ci),
                    ConsolidatedItem::TypeAlias(ci) => result.add_type_alias(ci),
                    ConsolidatedItem::Macro(ci)     => result.add_macro(ci),
                    ConsolidatedItem::Module(mi)    => result.add_module(mi),
                    ConsolidatedItem::ImplBlock(ib) => result.add_impl(ib),

                    #[cfg(test)]
                    ConsolidatedItem::MockTest(ib)  => unimplemented!(),
                }
            }
        }

        info!("Crate interface consolidation complete.");
        Ok(result)
    }
}

